    for (int spatial4 = threadIdx.x; spatial4 < HW4; spatial4 += blockDim.x) {
        float4 v = xv[spatial4];
        v.x = (v.x > 0.0f ? v.x : 0.0f) + b;
        v.y = (v.y > 0.0f ? v.y : 0.0f) + b;
