    float4* xv = reinterpret_cast<float4*>(x) + nc * HW4;

    // First float4
    float4 v0 = xv[vec_base];
    v0.x = (v0.x > 0.0f ? v0.x : 0.0f) + b;
    v0.y = (v0.y > 0.0f ? v0.y : 0.0f) + b;
    v0.z = (v0.z > 0.0f ? v0.z : 0.0f) + b;
    v0.w = (v0.w > 0.0f ? v0.w : 0.0f) + b;
    xv[vec_base] = v0;

    // Second float4 (guarded)
    if (vec_base + 1 < HW4) {
        float4 v1 = xv[vec_base + 1];
        v1.x = (v1.x > 0.0f ? v1.x : 0.0f) + b;
        v1.y = (v1.y > 0.0f ? v1.y : 0.0f) + b;
        v1.z = (v1.z > 0.0f ? v1.z : 0.0f) + b;
        v1.w = (v1.w > 0.0f ? v1.w : 0.0f) + b;
        xv[vec_base + 1] = v1;
