#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

__global__ void relu_bias_add_slice_kernel(
    float* __restrict__ x,
    const float* __restrict__ bias,
    int NC, int C, int HW
) {
    int nc = blockIdx.y;
    int spatial = blockIdx.x * blockDim.x + threadIdx.x;
    if (nc >= NC || spatial >= HW) return;
    int c = nc % C;
    float b = bias[c];
    int base = nc * HW + spatial;
    float v = x[base];
    x[base] = (v > 0.0f ? v : 0.0f) + b;
}

__global__ void relu_bias_add_slice_vec4_kernel(
    float* __restrict__ x,
    const float* __restrict__ bias,
    int NC, int C, int HW4
) {
    int nc = blockIdx.y;
    int spatial4 = blockIdx.x * blockDim.x + threadIdx.x;
    if (nc >= NC || spatial4 >= HW4) return;
    int c = nc % C;
    float b = __ldg(&bias[c]);
    float4* xv = reinterpret_cast<float4*>(x) + nc * HW4 + spatial4;
    float4 v = *xv;
    v.x = (v.x > 0.0f ? v.x : 0.0f) + b;
    v.y = (v.y > 0.0f ? v.y : 0.0f) + b;
    v.z = (v.z > 0.0f ? v.z : 0.0f) + b;
    v.w = (v.w > 0.0f ? v.w : 0.0f) + b;
    *xv = v;
}

void launch_fused_epilogue(
    torch::Tensor x,
    torch::Tensor bias,
    cudaStream_t stream
) {
    int N  = x.size(0);
    int C  = x.size(1);
    int H  = x.size(2);
    int W  = x.size(3);
    int HW = H * W;
    int NC = N * C;

    bool aligned16 = (reinterpret_cast<uintptr_t>(x.data_ptr<float>()) % 16 == 0);

    if (aligned16 && HW % 4 == 0) {
        int HW4 = HW / 4;
        int threads = 256;
        int bx = (HW4 + threads - 1) / threads;
        dim3 grid(bx, NC);
        relu_bias_add_slice_vec4_kernel<<<grid, threads, 0, stream>>>(
            x.data_ptr<float>(),
            bias.data_ptr<float>(),
            NC, C, HW4
        );
    } else {
        int threads = 256;
        int bx = (HW + threads - 1) / threads;
        dim3 grid(bx, NC);
        relu_bias_add_slice_kernel<<<grid, threads, 0, stream>>>(
            x.data_ptr<float>(),
            bias.data_ptr<float>(),
            NC, C, HW
        );
    }
}

torch::Tensor conv_relu_biasadd_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor conv_bias,
    torch::Tensor extra_bias,
    int64_t stride_h, int64_t stride_w,
    int64_t pad_h, int64_t pad_w,
    int64_t dil_h, int64_t dil_w,
    int64_t groups
) {
    TORCH_CHECK(input.is_cuda() && input.dtype() == torch::kFloat32, "Input must be CUDA float32");
    TORCH_CHECK(weight.is_cuda() && weight.is_contiguous(), "Weight must be CUDA contiguous");
    TORCH_CHECK(input.dim() == 4, "Input must be 4-D");

    auto output = at::conv2d(
        input,
        weight,
        conv_bias,
        {stride_h, stride_w},
        {pad_h, pad_w},
        {dil_h, dil_w},
        groups
    );

    TORCH_CHECK(output.is_contiguous(), "Conv output must be contiguous for fused epilogue");

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    launch_fused_epilogue(output, extra_bias, stream);

    return output;
}
